mapper.sql:
p.`del_flag` = 0

    AND p.`ledger_no` LIKE CONCAT('%', #{q.ledgerNo}, '%')


    AND p.`road_name` LIKE CONCAT('%', #{q.roadName}, '%')


    AND p.`xzqh` = #{q.xzqh}


    AND p.`gnq` = #{q.gnq}


    AND p.`acceptance_type` = #{q.acceptanceType}


    AND p.`acceptance_result` = #{q.acceptanceResult}


    AND p.`status` = #{q.status}


    AND p.`acceptance_date` >= #{q.beginAcceptanceDate}


    AND p.`acceptance_date` <= #{q.endAcceptanceDate}


    AND p.`crzdbh` LIKE CONCAT('%', #{q.crzdbh}, '%')


    AND p.`dkmc` LIKE CONCAT('%', #{q.dkmc}, '%')


    AND p.`ptsslb` = #{q.ptsslb}


    AND p.`facility_id` = #{q.facilityId}


    AND p.`archive_id` = #{q.archiveId}


    AND p.`handover_date` >= #{q.beginHandoverDate}


    AND p.`handover_date` <= #{q.endHandoverDate}


    AND p.`complete_date` >= #{q.beginCompleteDate}


    AND p.`complete_date` <= #{q.endCompleteDate}


    AND p.`material_count` >= #{q.beginMaterialCount}


    AND p.`material_count` <= #{q.endMaterialCount}


    AND p.`create_time` >= CONCAT(#{q.beginCreateTime}, ' 00:00:00')


    AND p.`create_time` <= CONCAT(#{q.endCreateTime}, ' 23:59:59')




    AND (

        p.`has_sgxk` = 0
        p.`has_ysbg` = 0
        p.`has_jgtc` = 0
        p.`has_zljdbg` = 0
        p.`has_cljybg` = 0
        p.`has_ajbg` = 0
        p.`has_ghyshgz` = 0
        p.`has_jgbaba` = 0
        p.`has_dazxys` = 0
        p.`has_dlyjd` = 0
        p.`has_yhxy` = 0
        p.`has_jgwj` = 0
        p.`has_yjwj` = 0
        1 = 0

    )




    AND (
        p.`road_name` LIKE CONCAT('%', #{q.keyword}, '%')
        OR p.`ledger_no` LIKE CONCAT('%', #{q.keyword}, '%')
        OR p.`crzdbh` LIKE CONCAT('%', #{q.keyword}, '%')
        OR p.`dkmc` LIKE CONCAT('%', #{q.keyword}, '%')
    )

mapper.select:
SELECT COUNT(1)
FROM `t_road_acceptance_ledger` p
WHERE p.`del_flag` = 0
  AND p.`ledger_no` = #{ledgerNo}

    AND p.`id` <> #{excludeId}

SELECT a.`id` AS id, a.`archive_no` AS archiveNo, a.`archive_name` AS archiveName, a.`archive_type` AS archiveType, a.`secret_level` AS secretLevel, a.`retention` AS retention, a.`archive_year` AS archiveYear, a.`archive_date` AS archiveDate, a.`status` AS status, a.`xzqh` AS xzqh, a.`responsible_dept` AS responsibleDept, a.`facility_id` AS facilityId, a.`ptxmmc` AS ptxmmc, a.`crzdbh` AS crzdbh, a.`dkmc` AS dkmc, a.`ptsslb` AS ptsslb, a.`file_count` AS fileCount, a.`total_size` AS totalSize, a.`remark` AS remark, a.`create_time` AS createTime FROM `t_archive` a WHERE a.`del_flag` = 0 AND (
a.`facility_id` = #{facilityId}
a.`crzdbh` = #{crzdbh}
1 = 0
) ORDER BY a.`archive_year` DESC, a.`archive_no` DESC
LIMIT #{limit}

SELECT COUNT(1)
FROM `t_archive` a
WHERE a.`del_flag` = 0
  AND (


            a.`facility_id` = #{facilityId}


            a.`crzdbh` = #{crzdbh}

        1 = 0

  )

SELECT a.`id` AS id, a.`archive_no` AS archiveNo, a.`archive_name` AS archiveName, a.`archive_type` AS archiveType, a.`secret_level` AS secretLevel, a.`archive_year` AS archiveYear, a.`archive_date` AS archiveDate, a.`status` AS status, a.`xzqh` AS xzqh, a.`facility_id` AS facilityId, a.`ptxmmc` AS ptxmmc, a.`crzdbh` AS crzdbh, a.`dkmc` AS dkmc, a.`file_count` AS fileCount, a.`total_size` AS totalSize FROM `t_archive` a WHERE a.`del_flag` = 0
AND a.`facility_id` = #{facilityId}
AND a.`crzdbh` = #{crzdbh}
AND (a.`archive_no` LIKE CONCAT('%', #{keyword}, '%') OR a.`archive_name` LIKE CONCAT('%', #{keyword}, '%') OR a.`ptxmmc` LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY a.`archive_year` DESC, a.`archive_no` DESC
LIMIT #{limit}
